CREATE TABLE inbox_notifications(id BINARY(16) PRIMARY KEY,user_id BINARY(16) NOT NULL,event_type VARCHAR(64) NOT NULL,title VARCHAR(200) NOT NULL,body VARCHAR(1000) NOT NULL,request_id BINARY(16),read_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT fk_inbox_user FOREIGN KEY(user_id) REFERENCES user_accounts(id),INDEX ix_inbox_user(user_id,read_at,created_at)) ENGINE=InnoDB;
CREATE TABLE monitoring_access_buckets(token_id BINARY(16) NOT NULL,source_ip VARBINARY(16) NOT NULL,minute_start TIMESTAMP NOT NULL,count SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(token_id,source_ip,minute_start)) ENGINE=InnoDB;
CREATE TABLE outbound_integrations(id BINARY(16) PRIMARY KEY,name VARCHAR(128) NOT NULL,type ENUM('HTTP_CONNECT_PROXY','WECOM_GROUP_BOT','SMTP') NOT NULL,status ENUM('DRAFT','PUBLISHED','DISABLED') NOT NULL DEFAULT 'DRAFT',config_json JSON NOT NULL,secret_id BINARY(16),version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_by BINARY(16) NOT NULL,updated_by BINARY(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT fk_outbound_secret FOREIGN KEY(secret_id) REFERENCES secret_records(id),INDEX ix_outbound_type(type,status)) ENGINE=InnoDB;
CREATE TABLE audit_archives(id BINARY(16) PRIMARY KEY,range_start TIMESTAMP(6) NOT NULL,range_end TIMESTAMP(6) NOT NULL,event_count BIGINT UNSIGNED NOT NULL,sha256 BINARY(32) NOT NULL,signature BINARY(32) NOT NULL,signing_key_id BINARY(16) NOT NULL,storage_version_id BINARY(16),bucket VARCHAR(128),object_key VARCHAR(512),version_id VARCHAR(512),status ENUM('PENDING','VERIFIED','FAILED') NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),verified_at TIMESTAMP(6),UNIQUE KEY uk_archive_range(range_start,range_end)) ENGINE=InnoDB;
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'monitoring.manage' FROM roles WHERE code='SYSTEM_OPERATOR';
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'audit.read' FROM roles WHERE code IN ('AUDITOR','SECURITY_ADMIN');
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'notification.manage' FROM roles WHERE code='SYSTEM_OPERATOR';
